import json,sys
d=json.load(sys.stdin)
# Check structure
for k in d:
    v = d[k]
    if isinstance(v, dict):
        models = v.get('models', [])
        print(f'{k}: {len(models)} models')
        if models:
            for m in models[:3]:
                print(f'  - {m.get(\"id\", m) if isinstance(m, dict) else m}')
    elif isinstance(v, list):
        print(f'{k}: list of {len(v)}')
" 2>/dev/null

cd /root/.nanobot && python3 -c "
import json
with open('providers_models.json') as f:
    d = json.load(f)
print('Top keys:', list(d.keys())[:10])
print('Type:', type(d))
if isinstance(d, dict):
    for k,v in d.items():
        print(f'  {k}: type={type(v).__name__}', end='')
        if isinstance(v, list):
            print(f' len={len(v)}')
        elif isinstance(v, dict):
            print(f' keys={list(v.keys())[:5]}')
        else:
            print(f' val={v}')
" 2>/dev/null
